package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoMomentHighlightReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun catalog()=VideoMomentNotes(5000,listOf(VideoMomentNote(1000,"First"),VideoMomentNote(3500,"Later")))
 private fun fixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoBatchReview>{val a=activity();val p=get(a,"project")as VideoEditProject;val d=dialog();val r=VideoBatchReview(p.segments,p.soundtrack);r.open(d);r.propose(d,VideoMomentHighlights.propose(p.segments,0,catalog().notes.map{it.sourceMs},500,500));set(a,"batchReviewRequest",r);set(a,"batchReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoBatchReview,review:VideoCaptionReviewState,load:()->VideoMomentNotes={catalog()})=call(a,"commitMomentHighlightsReview",d,r,review,catalog(),load)as Boolean
 @Test fun freshCatalogAppliesOnlyOnceWithOneUndoAndRetainedMusic(){val(a,d,r)=fixture();val review=capture(a);val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;var loads=0;assertTrue(commit(a,d,r,review){loads++;catalog()});assertEquals(1,loads);assertEquals(listOf(500L to 1500L,3000L to 4000L),p.segments.map{it.startMs to it.endMs});assertSame(music,p.soundtrack);assertEquals(listOf(before[0].captions.last()),p.segments.first().captions);assertEquals(before[0].captionSourceUri,p.segments.first().captionSourceUri);assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo);assertFalse(commit(a,d,r,review){fail("second load");catalog()});assertTrue(p.canRedo)}
 @Test fun renamedRemovedAddedOrDurationChangedCatalogConsumesWithoutMutation(){val expected=catalog();val variants=listOf(expected.rename(expected.notes[0],"Changed"),expected.remove(expected.notes[0]),expected.add(VideoMomentNote(4500,"New")),VideoMomentNotes(5001,expected.notes));for(next in variants){val(a,d,r)=fixture();val p=get(a,"project")as VideoEditProject;val before=p.segments;try{commit(a,d,r,capture(a)){next};fail("accepted changed notes")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalStateException)};assertTrue(r.isClosed);assertSame(before,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundSourceDurationSelectionGenerationSessionRecoveryAndBusyRefuseBeforeLoad(){for(flag in listOf("pause","source","duration","selection","generation","mode","recovery","busy","analysis")){val(a,d,r)=fixture();val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"selection"->set(a,"selectedClip",1);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);else->set(a,"analyzing",true)};assertFalse(flag,commit(a,d,r,review){fail("stale read");catalog()});assertTrue(r.isClosed);assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun sourceChangeDuringCatalogReadIsRecheckedBeforeMutation(){val(a,d,r)=fixture();val review=capture(a);val p=get(a,"project")as VideoEditProject;val before=p.segments;try{commit(a,d,r,review){set(a,"source",Uri.parse("content://synthetic/replaced"));catalog()};fail("accepted")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalStateException)};assertTrue(r.isClosed);assertSame(before,p.segments);assertFalse(p.canUndo)}
 @Test fun failedCatalogReadConsumesApprovalAndPreservesProject(){val(a,d,r)=fixture();val review=capture(a);val p=get(a,"project")as VideoEditProject;val before=p.segments;try{commit(a,d,r,review){error("read failed")};fail("accepted")}catch(e:java.lang.reflect.InvocationTargetException){assertEquals("read failed",e.cause?.message)};assertTrue(r.isClosed);assertSame(before,p.segments);assertFalse(commit(a,d,r,review){fail("retry read");catalog()})}
 @Test fun olderDialogCannotConsumeSuccessorApproval(){val(a,old,r)=fixture();val review=capture(a);val next=dialog();r.open(next);val p=get(a,"project")as VideoEditProject;r.propose(next,VideoMomentHighlights.propose(p.segments,0,listOf(1000L),500,500));set(a,"batchReviewDialog",next);set(a,"captionReviewDialogs",linkedSetOf(next));assertFalse(commit(a,old,r,review){fail("old read");catalog()});assertTrue(r.owns(next));assertTrue(commit(a,next,r,review))}
 @Test fun hiddenOrUntrackedConfirmationsCannotReadOrApply(){for(flag in listOf("hidden","untracked")){val(a,d,r)=fixture();val review=capture(a);if(flag=="hidden")showing(d,false)else set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertFalse(commit(a,d,r,review){fail("read");catalog()});assertTrue(r.isClosed);assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun backToEditorStageClearsOldProposalAndLateDismissCannotCloseIt(){val(a,d,r)=fixture();val review=capture(a);val editor=dialog();assertTrue(r.open(editor));r.dismiss(d);set(a,"batchReviewDialog",editor);set(a,"captionReviewDialogs",linkedSetOf(editor));assertTrue(r.owns(editor));assertFalse(commit(a,d,r,review){fail("old confirmation read");catalog()});assertFalse(commit(a,editor,r,review){fail("unprepared editor read");catalog()});assertTrue(r.owns(editor));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
 @Test fun invalidHandlesAndNoSelectionRemainEditableWithoutHistory(){val(a,d,r)=fixture();val p=get(a,"project")as VideoEditProject;for(points in listOf(emptyList(),listOf(9999L))){assertTrue(runCatching{VideoMomentHighlights.propose(p.segments,0,points,500,500)}.isFailure);assertTrue(r.owns(d))};assertTrue(runCatching{VideoMomentHighlights.propose(p.segments,0,listOf(1000L),-1,500)}.isFailure);assertTrue(r.owns(d));assertFalse(p.canUndo)}
 @Test fun lifecycleClosesApprovalAndPausedBusyRecoveryEntryPrecedesStorage(){val(a,d,r)=fixture();set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());call(a,"invalidateCaptionReviews");assertTrue(r.isClosed);assertNull(get(a,"batchReviewRequest"));assertNull(get(a,"batchReviewDialog"));for(flag in listOf("pause","busy","recovery")){val b=activity();when(flag){"pause"->set(b,"workspaceActive",false);"busy"->set(b,"saving",true);else->set(b,"recoveryBytes",byteArrayOf(1))};call(b,"momentHighlights");assertNull(get(b,"batchReviewRequest"));assertNull(get(b,"captionReviewDialogs"));assertFalse((get(b,"project")as VideoEditProject).canUndo)}}
}
